// Writes one content.ts per module folder.
//
// Why a generated file rather than a bundler setting: a chunking rule that
// groups already-split files turns them into static imports of the entry, so
// the whole course downloads before the map paints — the exact thing the split
// was for. A module folder that imports its own prose is a real module, so the
// bundler splits it the ordinary way, and one dynamic import fetches one
// module's content.
//
// Run by `npm run gen:content`; `npm run verify` fails if these are stale.
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

export const ROOT = fileURLToPath(new URL('..', import.meta.url))
export const MODULES = join(ROOT, 'src/course/modules')

export const moduleDirs = () =>
  readdirSync(MODULES, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && existsSync(join(MODULES, entry.name, 'module.ts')))
    .map((entry) => entry.name)
    .sort()

export function entrySource(dir) {
  return `// Generated by scripts/gen-content-entries.mjs — do not edit by hand.
//
// Everything ${dir} needs a learner to read or run, in one module, so the
// bundler makes it one chunk that is fetched when a project here is opened.
const files = import.meta.glob('./**/*.{md,py}', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>

export default files
`
}

if (import.meta.url === `file://${process.argv[1]}`) {
  let written = 0
  for (const dir of moduleDirs()) {
    const path = join(MODULES, dir, 'content.ts')
    const next = entrySource(dir)
    if (existsSync(path) && readFileSync(path, 'utf8') === next) continue
    writeFileSync(path, next)
    written++
    console.log(`  wrote ${dir}/content.ts`)
  }
  console.log(written ? `\n${written} content entr${written === 1 ? 'y' : 'ies'} updated.` : 'All content entries are current.')
}
